// The Vite plugin that assembles the web part (`vite build --mode web`): the static source tree, the UI that was just
// built and a generated `VersionInfo.mjs`. Vite calls its `closeBundle` hook once the UI is written; the tests call it
// the same way, on a source tree of their own, with git replaced by a function that answers like the commands do.
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const OLD_VERSION_INFO = '// generated by an earlier build';
const SHA = 'abcdef0123456789abcdef0123456789abcdef01';
const INCLUDE = ['index.html', 'js', 'img', 'mjs', 'ui/dist'];

const git = vi.fn();
let webBundle = null;
let root = null;
let source = null;
let target = null;

beforeAll(async () => {
    vi.doMock('node:child_process', () => ({ execFileSync: (...args) => git(...args) }));
    ({ webBundle } = await import('../../../vite.web-bundle.mjs'));
});

afterAll(() => {
    vi.doUnmock('node:child_process');
});

beforeEach(() => {
    root = fs.mkdtempSync(path.join(os.tmpdir(), 'rakkomik-bundle-'));
    source = path.join(root, 'web');
    target = path.join(root, 'build', 'web');
    const files = {
        'index.html': '<html>start page</html>',
        'js/fflate.mjs': 'export const zip = 1;',
        'img/logo_s.png': Buffer.from([137, 80, 78, 71, 0, 255]),
        'mjs/VersionInfo.mjs': OLD_VERSION_INFO,
        'mjs/engine/Engine.mjs': 'export default class Engine {}',
        'mjs/connectors/System.mjs': 'export default class System {}',
        'ui/dist/ui.js': 'export const ui = 1;',
        'ui/dist/ui.css': 'body {}',
        // the sources of the UI are not part of the bundle
        'ui/main.jsx': 'render();',
        'notes.txt': 'not listed',
    };
    for (const [name, content] of Object.entries(files)) {
        const file = path.join(source, ...name.split('/'));
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, content);
    }
    vi.stubEnv('RAKKOMIK_BRANCH', '');
    answer({});
});

afterEach(() => {
    vi.unstubAllEnvs();
    git.mockReset();
    fs.rmSync(root, { recursive: true, force: true });
});

// git answers with what `map` holds for its arguments (an Error is thrown), and fails for anything that is not listed
function answer(map) {
    const answers = {
        'rev-parse --abbrev-ref HEAD': 'main\n',
        'rev-parse HEAD': `${SHA}\n`,
        ...map,
    };
    git.mockImplementation((command, args) => {
        const key = args.join(' ');
        if (!(key in answers)) {
            throw new Error(`unexpected git ${key}`);
        }
        if (answers[key] instanceof Error) {
            throw answers[key];
        }
        return answers[key];
    });
}

function listing(directory) {
    return fs
        .readdirSync(directory, { recursive: true, withFileTypes: true })
        .filter((entry) => entry.isFile())
        .map((entry) =>
            path
                .relative(directory, path.join(entry.parentPath, entry.name))
                .split(path.sep)
                .join('/'),
        )
        .sort();
}

// the generated module is `export default { ... };`: read the object without a loader for modules
function versionInfo() {
    const text = fs.readFileSync(path.join(target, 'mjs', 'VersionInfo.mjs'), 'utf8');
    expect(text.startsWith('export default {')).toBe(true);
    return new Function(`return (${text.replace(/^export default /, '').replace(/;\s*$/, '')});`)();
}

function bundle(include = INCLUDE) {
    return webBundle({ source, target, include });
}

describe('webBundle', () => {
    it('should be a plugin of the build that has one hook, which runs when the bundle of the UI is written', () => {
        const plugin = bundle();
        expect(plugin.name).toBe('rakkomik-web-bundle');
        expect(plugin.apply).toBe('build');
        expect(Object.keys(plugin).sort()).toEqual(['apply', 'closeBundle', 'name']);
        expect(plugin.closeBundle).toBeInstanceOf(Function);
    });

    it('should do nothing before the hook is called', () => {
        bundle();
        expect(fs.existsSync(target)).toBe(false);
        expect(git).not.toHaveBeenCalled();
    });

    describe('closeBundle', () => {
        it('should copy what the list names, whole folders included, and nothing else', async () => {
            await bundle().closeBundle();
            expect(listing(target)).toEqual([
                'img/logo_s.png',
                'index.html',
                'js/fflate.mjs',
                'mjs/VersionInfo.mjs',
                'mjs/connectors/System.mjs',
                'mjs/engine/Engine.mjs',
                'ui/dist/ui.css',
                'ui/dist/ui.js',
            ]);
            expect(fs.readFileSync(path.join(target, 'img', 'logo_s.png'))).toEqual(
                Buffer.from([137, 80, 78, 71, 0, 255]),
            );
            expect(fs.readFileSync(path.join(target, 'ui', 'dist', 'ui.js'), 'utf8')).toBe(
                'export const ui = 1;',
            );
        });

        it('should start from an empty folder: what an earlier bundle left there is gone', async () => {
            fs.mkdirSync(path.join(target, 'mjs'), { recursive: true });
            fs.writeFileSync(path.join(target, 'old.js'), 'old');
            fs.writeFileSync(path.join(target, 'mjs', 'Removed.mjs'), 'removed since');
            await bundle().closeBundle();
            expect(listing(target)).not.toContain('old.js');
            expect(listing(target)).not.toContain('mjs/Removed.mjs');
        });

        it('should write the version into the bundle and leave the source tree as it is', async () => {
            const before = listing(source);
            await bundle().closeBundle();
            expect(fs.readFileSync(path.join(source, 'mjs', 'VersionInfo.mjs'), 'utf8')).toBe(
                OLD_VERSION_INFO,
            );
            expect(listing(source)).toEqual(before);
            expect(fs.readFileSync(path.join(target, 'mjs', 'VersionInfo.mjs'), 'utf8')).not.toBe(
                OLD_VERSION_INFO,
            );
        });

        it('should be repeatable', async () => {
            const plugin = bundle();
            await plugin.closeBundle();
            const first = listing(target);
            await plugin.closeBundle();
            expect(listing(target)).toEqual(first);
        });

        it('should fail, naming the path, when something in the list does not exist (the UI was not built)', async () => {
            fs.rmSync(path.join(source, 'ui', 'dist'), { recursive: true });
            await expect(bundle().closeBundle()).rejects.toThrow(/ENOENT.*dist/);
        });
    });

    describe('the version of the bundle', () => {
        it('should name the branch and the revision of the checkout, with a link to each', async () => {
            await bundle().closeBundle();
            expect(versionInfo()).toEqual({
                branch: { label: 'main', link: 'https://github.com/akn19/rakkomik/commits/main' },
                revision: {
                    label: 'abcdef',
                    link: `https://github.com/akn19/rakkomik/commits/${SHA}`,
                },
            });
        });

        it('should ask git, and keep its error out of the log of the build', async () => {
            await bundle().closeBundle();
            const options = { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] };
            expect(git.mock.calls).toEqual([
                ['git', ['rev-parse', '--abbrev-ref', 'HEAD'], options],
                ['git', ['rev-parse', 'HEAD'], options],
            ]);
        });

        it('should keep a branch with a slash as it is', async () => {
            answer({ 'rev-parse --abbrev-ref HEAD': 'feature/web-part\n' });
            await bundle().closeBundle();
            expect(versionInfo().branch).toEqual({
                label: 'feature/web-part',
                link: 'https://github.com/akn19/rakkomik/commits/feature/web-part',
            });
        });

        it('should name the tag of a checkout that is detached at one, which is how a release is built', async () => {
            answer({
                'rev-parse --abbrev-ref HEAD': 'HEAD\n',
                'describe --tags --exact-match HEAD': 'v1.2.3\n',
            });
            await bundle().closeBundle();
            expect(versionInfo().branch).toEqual({
                label: 'v1.2.3',
                link: 'https://github.com/akn19/rakkomik/commits/v1.2.3',
            });
        });

        it('should call a detached checkout that is not at a tag HEAD', async () => {
            answer({
                'rev-parse --abbrev-ref HEAD': 'HEAD\n',
                'describe --tags --exact-match HEAD': new Error('no tag exactly matches'),
            });
            await bundle().closeBundle();
            expect(versionInfo().branch.label).toBe('HEAD');
        });

        it('should not look for a tag on a checkout that has a branch', async () => {
            await bundle().closeBundle();
            expect(git.mock.calls.map((call) => call[1].join(' '))).not.toContain(
                'describe --tags --exact-match HEAD',
            );
        });

        it('should take the name from RAKKOMIK_BRANCH when it is set, which is how a package gets the tag it is built from', async () => {
            vi.stubEnv('RAKKOMIK_BRANCH', 'v9.9.9');
            await bundle().closeBundle();
            expect(versionInfo().branch).toEqual({
                label: 'v9.9.9',
                link: 'https://github.com/akn19/rakkomik/commits/v9.9.9',
            });
            // git is only asked for the revision then
            expect(git.mock.calls.map((call) => call[1].join(' '))).toEqual(['rev-parse HEAD']);
        });

        it('should fail the build when git does not answer, rather than ship a bundle with a version that is not its own', async () => {
            answer({ 'rev-parse HEAD': new Error('fatal: not a git repository') });
            await expect(bundle().closeBundle()).rejects.toThrow('fatal: not a git repository');
        });

        it('should write a branch with a quote so that the module is still valid and holds the same name', async () => {
            answer({ 'rev-parse --abbrev-ref HEAD': "it's-a-fix\n" });
            await bundle().closeBundle();
            expect(versionInfo().branch.label).toBe("it's-a-fix");
        });
    });
});
